/*
 * policy_infer.h
 *
 * Forward pass for the trained PPO policy:
 *   obs[OBS_DIM] -> Linear+Tanh (policy_w0/b0) -> Linear+Tanh (policy_w1/b1)
 *                -> Linear (action_w/b, no activation) -> clamp(ACTION_LOW, ACTION_HIGH)
 *
 * Requires policy_weights.h (generated by export_weights_to_header.py) to be
 * included first, or included from within this file -- adjust the #include
 * below if you keep them in different folders.
 */

#pragma once
#include <math.h>
#include "policy_weights.h"

// out = tanh(W * in + b), where W is (out_dim x in_dim) row-major
static void linear_tanh(const float *W, const float *b, const float *in,
                         float *out, int in_dim, int out_dim) {
    for (int i = 0; i < out_dim; i++) {
        float sum = b[i];
        const float *w_row = W + (long)i * in_dim;
        for (int j = 0; j < in_dim; j++) {
            sum += w_row[j] * in[j];
        }
        out[i] = tanhf(sum);
    }
}

// out = W * in + b, no activation (used for the final action_net layer)
static void linear(const float *W, const float *b, const float *in,
                    float *out, int in_dim, int out_dim) {
    for (int i = 0; i < out_dim; i++) {
        float sum = b[i];
        const float *w_row = W + (long)i * in_dim;
        for (int j = 0; j < in_dim; j++) {
            sum += w_row[j] * in[j];
        }
        out[i] = sum;
    }
}

/*
 * policy_forward: run the full network on one observation and return the
 * clamped action(s) in `action_out` (caller-allocated, length ACTION_DIM).
 */
static void policy_forward(const float obs[OBS_DIM], float action_out[ACTION_DIM]) {
    float hidden0[HIDDEN0_DIM];
    float hidden1[HIDDEN1_DIM];
    float raw_action[ACTION_DIM];

    linear_tanh(&POLICY_W0[0][0], POLICY_B0, obs, hidden0, OBS_DIM, HIDDEN0_DIM);
    linear_tanh(&POLICY_W1[0][0], POLICY_B1, hidden0, hidden1, HIDDEN0_DIM, HIDDEN1_DIM);
    linear(&ACTION_W[0][0], ACTION_B, hidden1, raw_action, HIDDEN1_DIM, ACTION_DIM);

    for (int i = 0; i < ACTION_DIM; i++) {
        float v = raw_action[i];
        if (v < ACTION_LOW[i]) v = ACTION_LOW[i];
        if (v > ACTION_HIGH[i]) v = ACTION_HIGH[i];
        action_out[i] = v;
    }
}